    <script>
    document.addEventListener('DOMContentLoaded', () => {
        class StoryRenderer {
            constructor(dataSourceId) {
                this.dataSourceId = dataSourceId;
                this.yamlData = null;
                this.init();
            }

            init() {
                try {
                    this.loadYaml();
                    const rootNodeKey = Object.keys(this.yamlData)[0];
                    const data = this.yamlData[rootNodeKey];
                    this.renderHeader(data);
                    this.renderCharacters(data);
                    this.renderActionOptions(data);
                } catch (error) {
                    console.error("渲染时发生错误:", error);
                    document.getElementById('characters-container').innerHTML = `<div class="text-red-500">错误: ${error.message}</div>`;
                }
            }

            loadYaml() {
                const scriptElement = document.getElementById(this.dataSourceId);
                if (!scriptElement) throw new Error("未找到YAML数据源");
                const yamlContent = scriptElement.textContent.trim();
                if (!yamlContent) throw new Error("YAML数据为空");
                this.yamlData = jsyaml.load(yamlContent);
            }

            findField(data, keywords) {
                const key = Object.keys(data).find(k => keywords.some(kw => k.toLowerCase().includes(kw)));
                return key ? data[key] : null;
            }

            cleanText(text) {
                return text ? text.toString().replace(/[\u{1F000}-\u{1FAFF}]/gu, '').trim() : '';
            }

            getEmoji(text) {
                if (!text) return '';
                const match = text.toString().match(/[\u{1F000}-\u{1FAFF}]/gu);
                return match ? match[0] : '';
            }

            renderHeader(data) {
                const timeStr = this.findField(data, ['时间', '日期', 'time']);
                const locationStr = this.findField(data, ['地点', '位置', 'location']);

                const timeEl = document.querySelector('#time-display span');
                const locationEl = document.querySelector('#location-display span');
                const timeIcon = document.querySelector('#time-display i');
                const locationIcon = document.querySelector('#location-display i');

                if (timeStr) {
                    timeEl.textContent = this.cleanText(timeStr);
                    timeIcon.className = `fa ${this.getEmoji(timeStr) ? '' : 'fa-clock-o'} mr-1.5`;
                    if(this.getEmoji(timeStr)) timeIcon.textContent = this.getEmoji(timeStr);
                }
                 if (locationStr) {
                    locationEl.textContent = this.cleanText(locationStr);
                    locationIcon.className = `fa ${this.getEmoji(locationStr) ? '' : 'fa-map-marker'} mr-1.5`;
                    if(this.getEmoji(locationStr)) locationIcon.textContent = this.getEmoji(locationStr);
                }
            }

            renderCharacters(data) {
                const container = document.getElementById('characters-container');
                const userList = this.findField(data, ['用户列表', '用户', '角色', 'user']);

                container.innerHTML = '';
                if (!userList || userList.length === 0) {
                    container.innerHTML = '<div class="text-center py-5 text-secondary">无角色信息</div>';
                    return;
                }

                userList.forEach(item => {
                    const characterData = item.用户 || item;
                    const card = this.createCharacterCard(characterData);
                    container.appendChild(card);
                });
            }

            createCharacterCard(data) {
                const name = this.findField(data, ['名字', 'name']);
                const bendLevel = this.findField(data, ['掰弯度', 'bend']);

                const card = document.createElement('div');
                card.className = 'character-card rounded-lg border p-4 theme-transition card-hover';

                let html = `<h4 class="font-bold text-lg text-main mb-3 flex items-center">${this.getEmoji(name) || '👤'} ${this.cleanText(name)}</h4>`;

                if (bendLevel !== null) {
                    html += this.createBendOMeter(this.cleanText(bendLevel));
                }

                html += '<ul class="space-y-2 text-sm mt-3">';
                for (const key in data) {
                    if (['名字', '掰弯度'].some(k => key.toLowerCase().includes(k))) continue;

                    const value = data[key];
                    const emoji = this.getEmoji(value) || '🔹';
                    let contentHtml = '';

                    // 修改：增加对Array类型的处理
                    if (Array.isArray(value)) {
                        const arrayContent = value.map(item => {
                            if (typeof item === 'object' && item !== null) {
                                return Object.entries(item).map(([subKey, subValue]) => `${this.cleanText(subValue)}`).join('; ');
                            }
                            return this.cleanText(item);
                        }).join(', ');
                        if(arrayContent) contentHtml = `<span class="text-secondary">${arrayContent}</span>`;
                    } else if (typeof value === 'object' && value !== null) {
                        const objectContent = Object.entries(value).map(([sk, sv]) => `${sk}: ${this.cleanText(sv)}`).join(', ');
                        if (objectContent) contentHtml = `<span class="text-secondary">${objectContent}</span>`;
                    } else {
                        const cleanValue = this.cleanText(value);
                        if (cleanValue) contentHtml = `<span class="text-secondary">${cleanValue}</span>`;
                    }

                    if (contentHtml) {
                         html += `<li class="flex items-start"><span class="opacity-80 mr-2">${this.getEmoji(data[key]) || emoji}</span><strong class="font-medium text-main mr-2">${key}:</strong> ${contentHtml}</li>`;
                    }
                }
                html += '</ul>';

                card.innerHTML = html;
                return card;
            }

            createBendOMeter(value) {
                const bendValue = parseInt(value, 10);
                if (isNaN(bendValue)) return '';

                const bendPercentage = Math.min(Math.max(bendValue, 0), 100);
                // 修改：增加曲率，将乘数从45调整到70
                const controlY = 50 + (bendPercentage / 100) * 70;
                const title = bendPercentage < 20 ? '钢铁直男' : bendPercentage < 50 ? '开始动摇' : bendPercentage < 80 ? '逐渐接受' : '彻底沉沦';

                return `
                    <div class="bend-o-meter mt-2">
                        <div class="flex justify-between items-center text-xs text-secondary mb-1">
                            <span>${title}</span>
                            <span class="font-bold text-primary">${bendPercentage}%</span>
                        </div>
                        <div class="w-full h-12">
                            <svg viewBox="0 0 100 100" preserveAspectRatio="none" width="100%" height="100%">
                                <path d="M 0,50 Q 50,${controlY} 100,50" stroke-width="4" stroke="currentColor" fill="none" class="text-primary theme-transition" stroke-linecap="round"/>
                            </svg>
                        </div>
                    </div>
                `;
            }

            renderActionOptions(data) {
                const optionsData = this.findField(data, ['行动选项', '选项', 'option']);
                const ownerEl = document.querySelector('#action-owner span');
                const listEl = document.getElementById('options-list');

                listEl.innerHTML = '';
                if (!optionsData) {
                    ownerEl.textContent = '系统';
                    listEl.innerHTML = '<li class="pl-3 py-1 text-sm">无可用行动</li>';
                    return;
                }

                const owner = this.findField(optionsData, ['名字', 'owner']);
                ownerEl.textContent = this.cleanText(owner) || 'User';

                const optionsList = this.findField(optionsData, ['选项', 'choices']);
                if (optionsList && optionsList.length > 0) {
                    optionsList.forEach(opt => {
                        const li = document.createElement('li');
                        li.className = 'options-list-item pl-3 py-1.5 border-l-2 text-sm theme-transition';
                        li.textContent = opt.replace(/^\d+\.\s*/, '').trim();
                        li.onclick = () => this.triggerQuickReply(li.textContent);
                        listEl.appendChild(li);
                    });
                } else {
                    listEl.innerHTML = '<li class="pl-3 py-1 text-sm">思考中...</li>';
                }
            }

             triggerQuickReply(text) {
                if (!text || text.trim().length === 0) return;
                console.log(`Sending to ST: /send ${text}|/trigger`);
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${text}|/trigger`);
                }
            }
        }

        class ThemeSwitcher {
            constructor() {
                // 修改：作用目标改为容器包装器
                this.containerWrapper = document.querySelector('.status-container-wrapper');
                this.buttons = document.querySelectorAll('.theme-btn');
                this.init();
            }

            init() {
                const savedTheme = localStorage.getItem('storyTheme') || 'night';
                this.setTheme(savedTheme);

                this.buttons.forEach(button => {
                    button.addEventListener('click', () => {
                        const theme = button.dataset.theme;
                        this.setTheme(theme);
                        localStorage.setItem('storyTheme', theme);
                    });
                });
            }

            setTheme(themeName) {
                this.containerWrapper.classList.remove('night-mode', 'day-mode');
                this.containerWrapper.classList.add(`${themeName}-mode`);

                this.buttons.forEach(btn => {
                    if (btn.dataset.theme === themeName) {
                        btn.classList.add('active');
                    } else {
                        btn.classList.remove('active');
                    }
                });
            }
        }

        new StoryRenderer('yaml-data-source');
        new ThemeSwitcher();
    });
    </script>
</body>
</html>
